-- Migration 014: Planos PESADOS (caminhoes/truck/implemento/van)
-- Fonte: 026 - Planos.xlsx (tabela oficial LOOG pesados)
-- Precos: +10% markup aplicado em monthly_cents
-- Isolamento: coluna `source` separa esses planos dos leves

-- 1) Adicionar coluna source + colunas auxiliares (se nao existem)
alter table public.plans add column if not exists source text not null default 'leves-oficial';
alter table public.plans add column if not exists monthly_cents_original integer;
alter table public.plans add column if not exists acrescimos text;
create index if not exists plans_source_active_idx on public.plans (source, active);

-- Backfill: marca planos preexistentes como leves-oficial (ja eh o default)
update public.plans set source = 'leves-oficial' where source is null;

-- 2) Limpa seed anterior de pesados (idempotente)
delete from public.plans where source = 'pesados-026';

-- 3) Insere 76 planos da 026
insert into public.plans (
  slug, name, group_name, vehicle_type, vehicle_type_label,
  min_fipe_cents, max_fipe_cents, monthly_cents, monthly_cents_original,
  participation_type, participation_value,
  payment_options, extras, acrescimos, adhesion_service,
  sell_on_site, favorite, installments, year_limit,
  monthly_includes_adhesion, active, display_order, source
) values
